54:   assertIsObject(obj);
55: 
56:   const { id, jsonrpc, method, params } = obj;
57:   assertIsRequestId(id);
58:   assertIsJSONRPC2OrUndefined(jsonrpc);
59: 
60:   if (method === 'subscription.stop') {
61:     return {
62:       id,
63:       jsonrpc,
64:       method,
65:     };
66:   }
67:   assertIsProcedureType(method);
68:   assertIsObject(params);
69:   const { input: rawInput, path } = params;
